import kotlin.text.count

fun main() {
    val (l, str) = readLine()!!.split(" ")
    val fs = str.count { it == 'F' && str.indexOf("FS", str.indexOf(it)) != -1 } // Wait, simpler: count substrings
    // Kotlin standard library doesn't have a direct count(substring) on String like Go's strings.Count easily accessible without regex or manual loop.
    // But extension function `count` exists for Char. For substring:
    // We can use `str.split("FS").size - 1` or regex.
    // Let's use split approach for simplicity and no regex overhead.
    val fsCount = str.split("FS").size - 1
    val sfCount = str.split("SF").size - 1

    println(if (sfCount > fsCount) "YES" else "NO")
}

